  React.useEffect(() => {
    const generateStoreQr = async () => {
      try {
        let payload = "";
        const cleanSubdomain = (profSubdomain || myStore.subdomain || "shop").trim().toLowerCase();
        
        if (storeQrType === "url") {
          payload = `https://${cleanSubdomain}.platform.dz`;
        } else if (storeQrType === "whatsapp") {
          const rawNum = (profWa || profPhone || "").replace(/[^0-9]/g, "");
          const cleanNum = rawNum.startsWith("0") ? "213" + rawNum.substring(1) : rawNum;
          payload = `https://wa.me/${cleanNum || "213555000000"}?text=Bonjour%20${encodeURIComponent(profName || myStore.name)}%2C%20je%20souhaite%2520découvrir%2520vos%2520produits%2520!`;
        } else {
          // vcard / direct business card scan
          payload = `BEGIN:VCARD\nVERSION:3.0\nFN:${profName || myStore.name}\nORG:${profName || myStore.name} Boutique\nTEL;TYPE=WORK,VOICE:${profPhone || myStore.contact?.phone || ""}`;
          if (profPhones && profPhones.length > 0) {
            profPhones.forEach((ph, idx) => {
              payload += `\nTEL;TYPE=CELL,VOICE;Label="Support ${idx + 1}":${ph}`;
            });
          }
          if (profEmail) {
            payload += `\nEMAIL;TYPE=PREF,INTERNET:${profEmail}`;
          }
          payload += `\nURL:https://${cleanSubdomain}.platform.dz`;
          let note = "Social Links:";
          if (profWa) note += ` WhatsApp: ${profWa}`;
          if (profViber) note += ` Viber: ${profViber}`;
          if (profIg) note += ` Instagram: ${profIg}`;
          if (profFb) note += ` Facebook: ${profFb}`;
          if (profTiktok) note += ` TikTok: ${profTiktok}`;
          if (profSnapchat) note += ` Snapchat: ${profSnapchat}`;
          payload += `\nNOTE:${note}\nEND:VCARD`;
        }

        const dataUrl = await QRCode.toDataURL(payload, {
          width: 360,
          margin: 2,
          color: {
            dark: storeQrColor,
            light: "#ffffff"
          }
        });
        setStoreQrDataUrl(dataUrl);
      } catch (err) {
        console.error("Failed to generate storefront QR code:", err);
      }
    };

    generateStoreQr();
  }, [storeQrType, storeQrColor, profSubdomain, profPhone, profWa, profEmail, profName, profFb, profIg, profViber, profTiktok, profSnapchat, profPhones, myStore]);

  const handleDownloadStoreQr = () => {
    if (!storeQrDataUrl) return;
    const qrImg = new window.Image();
    qrImg.crossOrigin = "anonymous";
    qrImg.src = storeQrDataUrl;
    qrImg.onload = () => {
      const canvas = document.createElement("canvas");
      canvas.width = 360;
      canvas.height = 360;
      const ctx = canvas.getContext("2d");
      if (!ctx) return;

      // Draw standard QR code
      ctx.drawImage(qrImg, 0, 0, 360, 360);

      const downloadFinal = () => {
        const url = canvas.toDataURL("image/png");
        const link = document.createElement("a");
        link.href = url;
        const cleanName = (profName || myStore.name || "boutique").trim().toLowerCase().replace(/\s+/g, "-");
        link.download = `qr-${cleanName}-${storeQrType}.png`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
      };

      if (storeQrWithLogo && myStore.logo) {
        const logoImg = new window.Image();
        logoImg.crossOrigin = "anonymous";
        logoImg.src = myStore.logo;
        logoImg.onload = () => {
          const size = 56;
          const x = (360 - size) / 2;
          const y = (360 - size) / 2;
          
          // Draw white background backing backing box 
          ctx.fillStyle = "#ffffff";
          ctx.beginPath();
          if (ctx.roundRect) {
            ctx.roundRect(x - 4, y - 4, size + 8, size + 8, 10);
          } else {
            ctx.rect(x - 4, y - 4, size + 8, size + 8);
          }
          ctx.fill();

          // Draw store profile logo
          ctx.save();
          ctx.beginPath();
          if (ctx.roundRect) {
            ctx.roundRect(x, y, size, size, 8);
          } else {
            ctx.rect(x, y, size, size);
          }
          ctx.clip();
          ctx.drawImage(logoImg, x, y, size, size);
          ctx.restore();

          downloadFinal();
        };
        logoImg.onerror = () => {
          downloadFinal();
        };
      } else {
        downloadFinal();
      }
    };
  };

