  const handleAddStorySection = (type: string) => {
    const template = STORY_SECTION_TEMPLATES[type as keyof typeof STORY_SECTION_TEMPLATES];
    if (!template) return;
    const newSection = {
      id: `sec-${Date.now()}-${Math.random().toString(36).substring(2, 6)}`,
      type,
      title: template.title,
      visible: true,
      content: JSON.parse(JSON.stringify(template.content))
    };
    setWizardAdvancedStorySections([...wizardAdvancedStorySections, newSection]);
    if (setMerchantFeedbackMessage) {
      setMerchantFeedbackMessage(`✨ Section "${template.title}" added to your story builder!`);
    }
  };

  const handleDuplicateStorySection = (idx: number) => {
    const updated = [...wizardAdvancedStorySections];
    const sectionToClone = updated[idx];
    const cloned = {
      ...sectionToClone,
      id: `sec-${Date.now()}-${Math.random().toString(36).substring(2, 6)}`,
      title: `${sectionToClone.title} (Copy)`,
      content: JSON.parse(JSON.stringify(sectionToClone.content))
    };
    updated.splice(idx + 1, 0, cloned);
    setWizardAdvancedStorySections(updated);
    if (setMerchantFeedbackMessage) {
      setMerchantFeedbackMessage(`✨ Duplicated section "${sectionToClone.title}" successfully.`);
    }
  };

  const handleDeleteStorySection = (idx: number) => {
    const sectionName = wizardAdvancedStorySections[idx]?.title;
    const updated = wizardAdvancedStorySections.filter((_, i) => i !== idx);
    setWizardAdvancedStorySections(updated);
    if (setMerchantFeedbackMessage) {
      setMerchantFeedbackMessage(`🗑️ Removed section "${sectionName}".`);
    }
  };

  const handleToggleStorySectionVisibility = (idx: number) => {
    const updated = [...wizardAdvancedStorySections];
    updated[idx].visible = !updated[idx].visible;
    setWizardAdvancedStorySections(updated);
  };

  const handleMoveStorySectionUp = (idx: number) => {
    if (idx === 0) return;
    const updated = [...wizardAdvancedStorySections];
    const temp = updated[idx];
    updated[idx] = updated[idx - 1];
    updated[idx - 1] = temp;
    setWizardAdvancedStorySections(updated);
  };

  const handleMoveStorySectionDown = (idx: number) => {
    if (idx === wizardAdvancedStorySections.length - 1) return;
    const updated = [...wizardAdvancedStorySections];
    const temp = updated[idx];
    updated[idx] = updated[idx + 1];
    updated[idx + 1] = temp;
    setWizardAdvancedStorySections(updated);
  };

  const handleStorySectionDragStart = (e: React.DragEvent, index: number) => {
    e.dataTransfer.setData("text/plain", index.toString());
  };

  const handleStorySectionDrop = (e: React.DragEvent, targetIndex: number) => {
    const sourceIndex = parseInt(e.dataTransfer.getData("text/plain"), 10);
    if (isNaN(sourceIndex)) return;
    const updated = [...wizardAdvancedStorySections];
    const [removed] = updated.splice(sourceIndex, 1);
    updated.splice(targetIndex, 0, removed);
    setWizardAdvancedStorySections(updated);
  };

