        if (data.wizardAdvancedStoryEnabled !== undefined) setWizardAdvancedStoryEnabled(data.wizardAdvancedStoryEnabled);
        if (data.wizardAdvancedStorySections !== undefined) setWizardAdvancedStorySections(data.wizardAdvancedStorySections);
        if (data.wizardStoryDescriptionEnabled !== undefined) setWizardStoryDescriptionEnabled(data.wizardStoryDescriptionEnabled);
        if (data.wizardVariantsEnabled !== undefined) setWizardVariantsEnabled(data.wizardVariantsEnabled);
        if (data.wizardProductVariants !== undefined) setWizardProductVariants(data.wizardProductVariants);
        if (data.wizardBundleEnabled !== undefined) setWizardBundleEnabled(data.wizardBundleEnabled);
