  React.useEffect(() => {
    const handleMove = (clientX: number) => {
      if (!isDraggingSplit || !merchantSplitContainerRef.current) return;
      const containerRect = merchantSplitContainerRef.current.getBoundingClientRect();
      const relativeX = clientX - containerRect.left;
      const percentage = (relativeX / containerRect.width) * 100;
      if (percentage >= 25 && percentage <= 85) {
        setLeftPanelWidth(percentage);
      }
    };

    const handleMouseMove = (e: MouseEvent) => {
      handleMove(e.clientX);
    };

    const handleTouchMove = (e: TouchEvent) => {
      if (e.touches && e.touches.length > 0) {
        handleMove(e.touches[0].clientX);
      }
    };

    const handleEnd = () => {
      setIsDraggingSplit(false);
    };

    if (isDraggingSplit) {
      document.addEventListener("mousemove", handleMouseMove);
      document.addEventListener("mouseup", handleEnd);
      document.addEventListener("touchmove", handleTouchMove, { passive: true });
      document.addEventListener("touchend", handleEnd);
    }

    return () => {
      document.removeEventListener("mousemove", handleMouseMove);
      document.removeEventListener("mouseup", handleEnd);
      document.removeEventListener("touchmove", handleTouchMove);
      document.removeEventListener("touchend", handleEnd);
    };
  }, [isDraggingSplit]);

  const [temporaryVideoInput, setTemporaryVideoInput] = useState<string>("");
