  // QR Code Generation States
  const [qrModalProduct, setQrModalProduct] = useState<Product | null>(null);
  const [qrCodeDataUrl, setQrCodeDataUrl] = useState<string>("");
  const [copiedQrLink, setCopiedQrLink] = useState<boolean>(false);

  const handleGenerateQRCode = async (product: Product) => {
    try {
      const publicUrl = `https://${myStore.subdomain}/product/${product.id}`;
      const dataUrl = await QRCode.toDataURL(publicUrl, {
        width: 320,
        margin: 2,
        color: {
          dark: "#0f172a", // Deep slate
          light: "#ffffff" // White
        }
      });
      setQrCodeDataUrl(dataUrl);
      setQrModalProduct(product);
      setCopiedQrLink(false);
    } catch (err) {
      console.error("Failed to generate QR Code:", err);
    }
  };

  const handleCopyQrLink = (url: string) => {
    navigator.clipboard.writeText(url);
    setCopiedQrLink(true);
    setTimeout(() => setCopiedQrLink(false), 2000);
  };

  const handleDownloadQrCode = (productName: string) => {
    if (!qrCodeDataUrl) return;
    const link = document.createElement("a");
    link.href = qrCodeDataUrl;
    link.download = `qr-${productName.toLowerCase().replace(/\s+/g, "-")}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // Advanced Image Canvas Editor States
  const canvasRef = React.useRef<HTMLCanvasElement | null>(null);
  const [canvasFilterBrightness, setCanvasFilterBrightness] = useState<number>(150 / 1.5); // Default 100%
  const [canvasFilterContrast, setCanvasFilterContrast] = useState<number>(100);
  const [canvasFilterSaturation, setCanvasFilterSaturation] = useState<number>(100);
  const [canvasAspectRatio, setCanvasAspectRatio] = useState<"square" | "landscape">("square");
  const [canvasImageEnhanced, setCanvasImageEnhanced] = useState<boolean>(false);
  const [canvasDragOver, setCanvasDragOver] = useState<boolean>(false);
  const [canvasStatusMessage, setCanvasStatusMessage] = useState<string>("");

  // AI Description Optimizer States
  const [aiOptimizing, setAiOptimizing] = useState<boolean>(false);

  // Creative local copywriting data generator
  const generateAIPitch = (name: string, category: string) => {
    const cleanName = name.trim() || "Artisan Masterpiece";
    const samplePitches: Record<string, string[]> = {
      "Crafts": [
        `Discover the exquisite charm of this premium handcrafted ${cleanName}. Individually completed by master heritage creators in Algeria.`,
        `✨ HERITAGE DESIGN DETAILS:\n- 🌿 Materials: 100% locally sourced sustainable clay & wool\n- 🎨 Authenticity: Hand-etched historical geometric patterns\n- 🏠 Aesthetics: Timeless organic texture perfect for active display or living accents\n\nExperience ancestral Algerian legacy refined for contemporary luxury. Each piece carries ancient storytelling motifs directly to your space.`
      ],
      "Poterie": [
        `Authentic, high-fired premium ${cleanName}. Hand-sculpted in ancestral workshops using traditional regional silt clay and glazed with organic natural minerals.`,
        `✨ PRODUCT SPECIFICATIONS:\n- 🏺 Clay Body: Hand-pounded durable terra-cotta\n- 🎨 Glaze Profile: Non-toxic mineral pigment with unique color variations\n- 💧 Capacity & Care: Water-resistant, oven-safe, historical kitchen elegance\n\nA beautiful addition that honors culinary traditions and rustic authenticity.`
      ],
      "Bijouterie": [
        `Elevate your look with our meticulously detailed, genuine hand-wrought Berber silver ${cleanName}. Embellished with historic cloisonné enamel work and authentic natural Mediterranean coral.`,
        `✨ JEWELRY ATTRIBUTES:\n- 💍 Metal: Pure 925 Sterling Silver with custom geometric detailing\n- 🔴 Setting: Hand-selected authentic red coral nodes\n- 🔒 Clasp: High-durability historical filigree hinge lock\n\n heirloom piece representing prestigious craftsmanship and Berber elegance.`
      ],
      "Tapis & Textile": [
        `Invest in a pure, heritage-grade hand-woven Algerian wool ${cleanName}. Crafted knot-by-knot by master Kabyle weavers, showcasing rich vegetal-dyed threads and majestic historic motifs.`,
        `✨ TEXTILE DETAILS:\n- 🐑 Composition: 100% natural organic highland sheep wool\n- 🧪 Dyes: Organic safflower, indigo, and pomegranate husks\n- 📐 Density: Extra dense hand-knotted pile for supreme walking insulation\n\nA timeless cultural tapestry that lasts generations and enlivens high-traffic rooms.`
      ],
      "Alimentation": [
        `Taste the rich sunshine of Algeria with this premium, pure ${cleanName}. Earth-harvested and sun-dried according to standard traditional methods to lock in organic nutrients and delicious natural taste.`,
        `✨ FLAVOR PROFILE:\n- 🌴 Grade: Hand-picked Premium Selection\n- 🌿 Ingredients: 100% clean, no added sugars or preservatives\n- 🍯 Best Paired: Perfect for healthy snacking, culinary elevation, or culinary gifting\n\nAuthentic farm-to-table purity delivered direct and securely.`
      ],
      "default": [
        `Experience the high-end appeal of our optimized ${cleanName}. Designed to combine functionality with premium aesthetic details, bringing boutique quality directly to your life.`,
        `✨ HIGHLIGHTS & BENEFITS:\n- 🛡️ Quality: Multi-stage inspected for supreme durability\n- 📦 Custom Transit: Dynamic shock-absorb safe double-boxing\n- ⚡ Elite Edition: Exclusive small-batch creation supporting local makers\n\nEnrich your collection with a stunning item curated for seekers of quality.`
      ]
    };

    const key = samplePitches[category] ? category : "default";
    const paragraphs = samplePitches[key];
    return `${paragraphs[0]}\n\n${paragraphs[1]}`;
  };

  const handleAIOptimizeDescription = () => {
    if (!manualProductForm.name.trim()) {
      alert("Please specify a Product Item Name first so the AI can craft a custom sales pitch!");
      return;
    }

    setAiOptimizing(true);
    
    // Simulate active processing delay
    setTimeout(() => {
      const fullPitch = generateAIPitch(manualProductForm.name, manualProductForm.category);
      let currentLength = 0;
      setManualProductForm(prev => ({ ...prev, description: "" }));
      
      const interval = setInterval(() => {
        currentLength += Math.min(6, fullPitch.length - currentLength);
        if (currentLength >= fullPitch.length) {
          setManualProductForm(prev => ({ ...prev, description: fullPitch }));
          clearInterval(interval);
          setAiOptimizing(false);
        } else {
          setManualProductForm(prev => ({
            ...prev,
            description: fullPitch.substring(0, currentLength) + " ▌"
          }));
        }
      }, 15);
    }, 1200);
  };

  // Canvas Image Rendering Engine
  const drawCanvasImage = React.useCallback(() => {
    if (!canvasRef.current || !manualProductForm.imageUrl) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const img = new window.Image();
    img.crossOrigin = "anonymous";
    img.src = manualProductForm.imageUrl;
    img.onload = () => {
      // Set sizes based on crop standard
      if (canvasAspectRatio === "square") {
        canvas.width = 600;
        canvas.height = 600;
      } else {
        canvas.width = 800;
        canvas.height = 450;
      }

      // Center cropカバー fit
      const scale = Math.max(canvas.width / img.width, canvas.height / img.height);
      const x = (canvas.width - img.width * scale) / 2;
      const y = (canvas.height - img.height * scale) / 2;
      const w = img.width * scale;
      const h = img.height * scale;

      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Filters setup
      let filterStr = `brightness(${canvasFilterBrightness}%) contrast(${canvasFilterContrast}%) saturate(${canvasFilterSaturation}%)`;
      if (canvasImageEnhanced) {
        filterStr += ` contrast(112%) saturate(118%)`;
      }
      ctx.filter = filterStr;
      ctx.drawImage(img, x, y, w, h);

      // Apply real convolutional sharpening sharpen pass if requested
      if (canvasImageEnhanced) {
        try {
          const srcData = ctx.getImageData(0, 0, canvas.width, canvas.height);
          const src = srcData.data;
          const output = ctx.createImageData(canvas.width, canvas.height);
          const dst = output.data;
          const width = canvas.width;
          const height = canvas.height;
          // Weights for sharp high-pass
          const weights = [0, -0.2, 0, -0.2, 1.8, -0.2, 0, -0.2, 0];
          const side = Math.round(Math.sqrt(weights.length));
          const halfSide = Math.floor(side / 2);

          for (let cy = 0; cy < height; cy++) {
            for (let cx = 0; cx < width; cx++) {
              const dstOff = (cy * width + cx) * 4;
              let r = 0, g = 0, b = 0;
              for (let maskY = 0; maskY < side; maskY++) {
                for (let maskX = 0; maskX < side; maskX++) {
                  const pixelY = Math.min(height - 1, Math.max(0, cy + maskY - halfSide));
                  const pixelX = Math.min(width - 1, Math.max(0, cx + maskX - halfSide));
                  const srcOff = (pixelY * width + pixelX) * 4;
                  const wt = weights[maskY * side + maskX];
                  r += src[srcOff] * wt;
                  g += src[srcOff + 1] * wt;
                  b += src[srcOff + 2] * wt;
                }
              }
              dst[dstOff] = Math.min(255, Math.max(0, r));
              dst[dstOff + 1] = Math.min(255, Math.max(0, g));
              dst[dstOff + 2] = Math.min(255, Math.max(0, b));
              dst[dstOff + 3] = src[dstOff + 3]; // preserved aplha
            }
          }
          ctx.putImageData(output, 0, 0);
        } catch (e) {
          console.warn("CORS rules blocked image data sharpen pass.", e);
        }
      }
    };
    img.onerror = () => {
      console.warn("Could not load image to canvas");
    };
  }, [manualProductForm.imageUrl, canvasFilterBrightness, canvasFilterContrast, canvasFilterSaturation, canvasAspectRatio, canvasImageEnhanced]);

  // Handle local drawing reactivity
  React.useEffect(() => {
    if (isProductModalOpen && manualProductForm.imageUrl) {
      const timer = setTimeout(() => {
        drawCanvasImage();
      }, 150);
      return () => clearTimeout(timer);
    }
  }, [isProductModalOpen, manualProductForm.imageUrl, drawCanvasImage]);

  // Process and extract canvas back to manualProductForm's image thumbnail state
  const handleSaveCanvasState = () => {
    if (!canvasRef.current || !manualProductForm.imageUrl) return;
    try {
      const dataUrl = canvasRef.current.toDataURL("image/jpeg", 0.9);
      setManualProductForm(prev => {
        const oldUrl = prev.imageUrl;
        let updatedImages = prev.images ? [...prev.images] : [];
        const idx = updatedImages.indexOf(oldUrl);
        if (idx !== -1) {
          updatedImages[idx] = dataUrl;
        } else {
          if (updatedImages.length === 0) {
            updatedImages = [dataUrl];
          }
        }
        return {
          ...prev,
          imageUrl: dataUrl,
          images: updatedImages
        };
      });
      setCanvasStatusMessage("✨ Thumbnail updated with canvas-rendered filters successfully!");
      setTimeout(() => setCanvasStatusMessage(""), 4000);
    } catch (e) {
      console.warn(e);
      alert("Note: This remote image URL does not allow direct pixel extraction due to cross-origin policies. The raw image URL was preserved perfectly but filters will be rendered CSS-side or on physical uploads!");
    }
  };

  const handleAddImageToGallery = () => {
    if (!manualProductForm.imageUrl) return;
    const parts = manualProductForm.imageUrl
      .split(/[,\s;\n]+/)
      .map(part => part.trim())
      .filter(part => part.length > 0);
    
    if (parts.length === 0) return;

    setManualProductForm(prev => {
      const currentImages = prev.images || [];
      const nextImages = [...currentImages];
      parts.forEach(url => {
        if (!nextImages.includes(url)) {
          nextImages.push(url);
        }
      });
      return {
        ...prev,
        imageUrl: parts[parts.length - 1],
        images: nextImages
      };
    });
  };

  const handleAddVideoToGallery = () => {
    if (!temporaryVideoInput.trim()) return;
    const parts = temporaryVideoInput
      .split(/[,\s;\n]+/)
      .map(part => part.trim())
      .filter(part => part.length > 0);
    
    if (parts.length === 0) return;

    setManualProductForm(prev => {
      const currentVideos = prev.videoUrls || [];
      const nextVideos = [...currentVideos];
      const nextMetadata = prev.videoMetadata ? { ...prev.videoMetadata } : {};
      
      parts.forEach(url => {
        if (!nextVideos.includes(url)) {
          nextVideos.push(url);
        }
        // Associated metadata
        nextMetadata[url] = {
          duration: temporaryVideoDuration.trim() || "0:15",
          resolution: temporaryVideoResolution.trim() || "1080p",
          format: temporaryVideoFormat.trim() || "MP4"
        };
      });
      return {
        ...prev,
        videoUrl: prev.videoUrl || nextVideos[0] || "",
        videoUrls: nextVideos,
        videoMetadata: nextMetadata
      };
    });
    setTemporaryVideoInput("");
  };

  // States for Orders simulation and filtering with Arabic support
  const [merchantLang, setMerchantLang] = useState<"en" | "ar" | "fr">("en");
  
  React.useEffect(() => {
    if (currentLanguage === "ar") {
      setMerchantLang("ar");
    } else {
      setMerchantLang("en");
    }
  }, [currentLanguage]);

  const [connectedCouriers, setConnectedCouriers] = useState<Record<string, { apiKey: string; apiSecret?: string; connectedAt: string }>>(() => {
    const defaultConnected = {
      yalidine: {
        apiKey: "yal-live-default",
        apiSecret: "yal-sec-default",
        connectedAt: new Date().toISOString(),
      },
    };
    try {
      let saved = localStorage.getItem(`connected_couriers_${myStore.id}`);
      if (!saved) {
        saved = localStorage.getItem("connected_couriers");
      }
      if (!saved) return defaultConnected;
      
      const parsed = JSON.parse(saved);
      if (!parsed || typeof parsed !== "object" || Object.keys(parsed).length === 0) {
        return defaultConnected;
      }
      const decrypted: Record<string, any> = {};
      for (const k of Object.keys(parsed)) {
        decrypted[k] = {
          ...parsed[k],
          apiKey: decryptApiKey(parsed[k].apiKey, myStore.id),
          apiSecret: decryptApiKey(parsed[k].apiSecret, myStore.id),
        };
      }
      return decrypted;
    } catch {
      return defaultConnected;
    }
  });

  const [selectedCourierToLink, setSelectedCourierToLink] = useState<{ id: string; name: string; bg: string; logoText: string; brand?: string; svg?: any } | null>(null);
  const [courierApiKey, setCourierApiKey] = useState<string>("");
  const [courierApiSecret, setCourierApiSecret] = useState<string>("");

