  // Keep wizardDeliveryCompany synced to a connected company when available
  useEffect(() => {
    if (connectedDeliveryCompanies.length > 0) {
      const matchesConnected = connectedDeliveryCompanies.some(
        (c) => c.name === wizardDeliveryCompany || c.id === wizardDeliveryCompany
      );
      if (!matchesConnected) {
        setWizardDeliveryCompany(connectedDeliveryCompanies[0].name);
      }
    }
  }, [connectedDeliveryCompanies, wizardDeliveryCompany]);

  // Integrate delivery pricing with API when available, otherwise use manual pricing from dashboard
  useEffect(() => {
    const matchedCourier = connectedDeliveryCompanies.find(
      (c) => c.name === wizardDeliveryCompany || c.id === wizardDeliveryCompany
    );
    const manualDashboardFee = activeRates.isFlatRate ? activeRates.flatRateAmount : activeRates.algiers;
    let resolvedDeliveryCost = manualDashboardFee;

    if (matchedCourier && matchedCourier.hasApi) {
      const apiCalc = calculateDynamicShippingFee({
        carrier: matchedCourier.name,
        wilaya: wizardShippingWilaya,
        deliveryType: wizardDeliveryType,
        currency: wizardCurrency,
      });
      if (apiCalc && apiCalc.fee > 0) {
        resolvedDeliveryCost = apiCalc.fee;
      }
    }

    setWizardRealDeliveryCost(resolvedDeliveryCost);
    setWizardShippingCost(wizardShippingType === "free" ? 0 : resolvedDeliveryCost);
  }, [
    connectedDeliveryCompanies,
    wizardDeliveryCompany,
    wizardShippingWilaya,
    wizardDeliveryType,
    wizardCurrency,
    wizardShippingType,
    activeRates.isFlatRate,
    activeRates.flatRateAmount,
    activeRates.algiers,
  ]);

  const updateRate = (key: "algiers" | "major" | "sahara" | "standard" | "isFlatRate" | "flatRateAmount", val: any) => {
    if (!checkPermission("deliveryOperations", `Update Shipping Rate (${key})`, "Delivery Operations")) return;
    const updated = {
      ...activeRates,
      [key]: val
    };
    if (onChangeShippingRates) {
      onChangeShippingRates(updated);
    } else {
      localStorage.setItem("custom_shipping_rates", JSON.stringify(updated));
    }
    if (key === "isFlatRate") {
      setMerchantFeedbackMessage(val ? "Simplified Flat Rate Shipping activated!" : "Detailed Zone Shipping activated!");
    } else if (key === "flatRateAmount") {
      setMerchantFeedbackMessage(`Flat shipping price updated to ${val} DA across all regions!`);
    } else {
      setMerchantFeedbackMessage(`Updated ${key} province shipping price to ${val} DA!`);
    }
  };

  const handleUpdateOrderShippingCost = (newCost: number) => {
    if (!selectedOrderDetails) return;
    const subtotal = selectedOrderDetails.items.reduce((acc, it) => acc + it.price * it.quantity, 0);
    const nextTotal = subtotal + newCost;
    
    setSelectedOrderDetails(prev => prev ? {
      ...prev,
      shippingCost: newCost,
      total: nextTotal
    } : null);

    if (setOrders) {
      setOrders(prev => prev.map(o => o.id === selectedOrderDetails.id ? {
        ...o,
        shippingCost: newCost,
        total: nextTotal
      } : o));
    }
  };

  // State to capture order status transition animation and display a smooth slide-in notification Toast
  const [activeTransition, setActiveTransition] = useState<{
    id: string;
    shopperName: string;
    status: "pending" | "accepted" | "shipped" | "delivered";
  } | null>(null);

  const localUpdateOrderStatus = (orderId: string, nextStatus: "pending" | "accepted" | "shipped" | "delivered") => {
    // Permission Checks!
    if (nextStatus === "accepted" || nextStatus === "pending") {
      if (!checkPermission("confirmOrders", nextStatus === "accepted" ? "Confirm/Accept Order" : "Reset Order to Pending", "Confirm Orders")) return;
    }
    if (nextStatus === "shipped" || nextStatus === "delivered") {
      if (!checkPermission("prepareShipments", nextStatus === "shipped" ? "Prepare/Ship Order" : "Mark as Delivered", "Prepare Shipments")) return;
    }

    // Find customer/shopper details to display on slide-in banner
    const matchedOrder = (orders || []).find(o => o.id === orderId);
    const shopperName = matchedOrder?.shopper?.name || "Client";

    // Call underlying backend/state propagator prop
    handleUpdateOrderStatus(orderId, nextStatus);

    if (nextStatus === "delivered") {
      try {
        confetti({
          particleCount: 140,
          spread: 75,
          origin: { y: 0.6 },
          colors: ["#3b42f6", "#10b981", "#fbbf24", "#f43f5e", "#8b5cf6"]
        });
      } catch (err) {
        console.warn("Failed to fire confetti:", err);
      }
      if (matchedOrder) {
        try {
          generateMerchantReceiptPDF({ ...matchedOrder, status: "delivered" });
        } catch (pdfErr) {
          console.error("Failed to auto-generate PDF receipt:", pdfErr);
        }
      }
    }

    // Sync detailed order modal state if open
    if (selectedOrderDetails?.id === orderId) {
      setSelectedOrderDetails(prev => prev ? { ...prev, status: nextStatus } : null);
    }

    if (nextStatus === "shipped" || nextStatus === "delivered") {
      setActiveTransition({
        id: orderId,
        shopperName,
        status: nextStatus
      });
      // Automatically close or slide out after 4.5 seconds
      const timeoutId = setTimeout(() => {
        setActiveTransition(prev => prev?.id === orderId ? null : prev);
      }, 4500);
      return () => clearTimeout(timeoutId);
    }
  };

  const handleBulkUpdateStatus = (nextStatus: "pending" | "accepted" | "shipped" | "delivered") => {
    if (selectedOrderIds.length === 0) return;

    if (nextStatus === "accepted" || nextStatus === "pending") {
      if (!checkPermission("confirmOrders", nextStatus === "accepted" ? "Confirm/Accept Order" : "Reset Order to Pending", "Confirm Orders")) return;
    }
    if (nextStatus === "shipped" || nextStatus === "delivered") {
      if (!checkPermission("prepareShipments", nextStatus === "shipped" ? "Prepare/Ship Order" : "Mark as Delivered", "Prepare Shipments")) return;
    }

    let updatedCount = 0;
    selectedOrderIds.forEach(orderId => {
      handleUpdateOrderStatus(orderId, nextStatus);
      updatedCount++;
    });

    if (nextStatus === "delivered") {
      try {
        confetti({
          particleCount: 140,
          spread: 75,
          origin: { y: 0.6 },
          colors: ["#3b42f6", "#10b981", "#fbbf24", "#f43f5e", "#8b5cf6"]
        });
      } catch (err) {
        console.warn("Failed to fire confetti:", err);
      }
    }

    if (setMerchantFeedbackMessage) {
      setMerchantFeedbackMessage(
        merchantLang === "ar"
          ? `تم تحديث حالة ${updatedCount} طلبيات بنجاح إلى ${TRANSLATIONS.ar[nextStatus] || nextStatus}!`
          : `Successfully updated status of ${updatedCount} orders to ${TRANSLATIONS.en[nextStatus] || nextStatus}!`
      );
    }

    setSelectedOrderIds([]);
  };

  // Creative Profile and Dynamic status states
  const [merchantStatus, setMerchantStatus] = useState<"Online" | "Away" | "On Vacation">("Online");
  const [profileMotto, setProfileMotto] = useState<string>("Delivering quality handcrafted boutique items with worldwide logistics!");
  const [isMottoEditing, setIsMottoEditing] = useState<boolean>(false);
  const [selectedOrderDetails, setSelectedOrderDetails] = useState<Order | null>(null);
  const [trackingOrderModal, setTrackingOrderModal] = useState<Order | null>(null);
