  // --- STORIES MANAGEMENT STATES & SUBROUTINES ---
  const [activeEditingSlotIndex, setActiveEditingSlotIndex] = useState<number | null>(null);
  const [slotToDeleteIndex, setSlotToDeleteIndex] = useState<number | null>(null);
  const [modalDeleteConfirm, setModalDeleteConfirm] = useState<boolean>(false);
  const [modalValidationError, setModalValidationError] = useState<string>("");

  const [modalStoryType, setModalStoryType] = useState<"image" | "video" | "text">("image");
  const [modalMediaUrl, setModalMediaUrl] = useState<string>("");
  const [modalTextContent, setModalTextContent] = useState<string>("");
  const [modalDescription, setModalDescription] = useState<string>("");
  const [modalLinkedProductId, setModalLinkedProductId] = useState<string>("");
  const [modalHashtags, setModalHashtags] = useState<string>("");
