  const handleProfilePicChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        if (typeof reader.result === "string") {
          handleUpdateStoreProfile({ logo: reader.result });
          setMerchantFeedbackMessage("Profile picture updated!");
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleCoverPicChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    const readFilesPromises = Array.from(files).map((file: File) => {
      return new Promise<string>((resolve) => {
        const reader = new FileReader();
        reader.onloadend = () => {
          if (typeof reader.result === "string") {
            resolve(reader.result);
          } else {
            resolve("");
          }
        };
        reader.readAsDataURL(file);
      });
    });

    Promise.all(readFilesPromises).then((results) => {
      const validResults = results.filter((res) => res !== "");
      if (validResults.length > 0) {
        const currentBanners = myStore.banners || (myStore.banner ? [myStore.banner] : []);
        const nextBanners = [...currentBanners, ...validResults];
        
        handleUpdateStoreProfile({
          banner: nextBanners[0],
          banners: nextBanners
        });
        setCurrentMerchantBannerIdx(nextBanners.length - 1); // transition to the newly added slide
        setMerchantFeedbackMessage(`Successfully uploaded ${validResults.length} cover picture(s) to your slideshow!`);
      }
    });
  };

  const handleEditProductClick = (prod: any) => {
    setEditingProduct(prod);
    const prodShippingType: "paid" | "free" = prod.shippingType || (prod.shippingCost === 0 ? "free" : "paid");
    const prodPurchasePrice = prod.purchasePrice !== undefined ? prod.purchasePrice : (prod.buyPrice !== undefined ? prod.buyPrice : Math.round((Number(prod.price) || 3500) * 0.55));
    const prodRealDelivery = prod.realDeliveryCost !== undefined ? prod.realDeliveryCost : (prod.shippingCost || 450);
    setManualProductForm({
      name: prod.name,
      price: prod.price,
      purchasePrice: prodPurchasePrice,
      shippingCost: prodShippingType === "free" ? 0 : prodRealDelivery,
      realDeliveryCost: prodRealDelivery,
      shippingType: prodShippingType,
      deliveryCompany: prod.deliveryCompany || "Yalidine Express",
      description: prod.description || "",
      imageUrl: prod.imageUrl || "",
      category: prod.category || "Crafts",
      stock: prod.stock || 10,
      images: prod.images ? [...prod.images] : (prod.imageUrl ? [prod.imageUrl] : []),
      sku: prod.sku || "",
      colors: prod.colors ? [...prod.colors] : [],
      sizes: prod.sizes ? [...prod.sizes] : [],
      specifications: prod.specifications ? [...prod.specifications] : [],
      description_ar: prod.description_ar || "",
      description_fr: prod.description_fr || "",
      description_en: prod.description_en || "",
      videoUrl: prod.videoUrl || "",
      videoUrls: prod.videoUrls ? [...prod.videoUrls] : (prod.videoUrl ? [prod.videoUrl] : []),
      videoMetadata: prod.videoMetadata ? { ...prod.videoMetadata } : {},
      discountEnabled: !!prod.discountEnabled,
      discountPercent: prod.discountPercent !== undefined ? prod.discountPercent : 15,
      timerEnabled: !!prod.timerEnabled,
      timerHours: prod.timerHours !== undefined ? prod.timerHours : 24,
      timerStyle: (prod.timerStyle || "style_1") as FlashSaleTimerStyle,
      uploadedLandingPageContent: prod.uploadedLandingPageContent || "",
      advancedLandingPageEnabled: !!prod.advancedLandingPageEnabled,
    });
    
    // Set 6-step guided walkthrough wizard states
    setBlankProductName(prod.name || "");
    setBlankProductPrice(prod.price || 3500);
    setWizardPurchasePrice(prodPurchasePrice);
    setWizardShippingType(prodShippingType);
    setWizardRealDeliveryCost(prodRealDelivery);
    setBlankProductCategory(prod.category || "Crafts");
    setBlankProductSku(prod.sku || "");
    setBlankProductDescription(prod.description || "");
    setBlankProductNotes(prod.notes || "");
    setBlankProductBrandColor(prod.brandColor || "#6366f1");
    
    setWizardStep(1);
    setPreviewActiveImageIndex(0);
    
    const initialImages = prod.images && prod.images.length > 0 
      ? [...prod.images] 
      : (prod.imageUrl ? [prod.imageUrl] : ["", ""]);
    while (initialImages.length < 2) {
      initialImages.push("");
    }
    setWizardImages(initialImages);
    const initialVideos = prod.videoUrls && prod.videoUrls.length > 0 
      ? [...prod.videoUrls] 
      : (prod.videoUrl ? [prod.videoUrl] : []);
    setWizardLinks(initialVideos);
    setWizardProductStory(prod.description || "");
    setWizardShippingCost(prodShippingType === "free" ? 0 : prodRealDelivery);
    setWizardDeliveryCompany(prod.deliveryCompany || "Yalidine Express");
    
    if (prod.specifications && prod.specifications.length > 0) {
      setWizardProductSpecs(prod.specifications);
    } else {
      setWizardProductSpecs([
        { key: "Origin", value: "Algeria" }
      ]);
    }
    
    setWizardProductSizes(prod.sizes && prod.sizes.length > 0 ? prod.sizes : []);
    if (prod.sizePrices) {
      setWizardSizePrices(prod.sizePrices);
    } else if (prod.sizesWithPrices && Array.isArray(prod.sizesWithPrices)) {
      const spMap: Record<string, number | undefined> = {};
      prod.sizesWithPrices.forEach((s: any) => {
        if (s && s.name) spMap[s.name] = s.price;
      });
      setWizardSizePrices(spMap);
    } else {
      setWizardSizePrices({});
    }
    if (prod.colorVariantStyle) {
      setWizardColorDisplayStyle(prod.colorVariantStyle);
    }
    setWizardDetailedImagesPerColorEnabled(!!prod.detailedImagesPerColorEnabled);
    if (prod.detailedImagesByPrimary && typeof prod.detailedImagesByPrimary === "object") {
      setWizardDetailedImagesByPrimary(prod.detailedImagesByPrimary);
    } else if (prod.colors && Array.isArray(prod.colors)) {
      const reconstructedMap: Record<string, string[]> = {};
      prod.colors.forEach((c: any) => {
        if (typeof c === "object" && c) {
          const primary = c.imageUrl || (Array.isArray(c.images) && c.images[0]) || "";
          if (primary && Array.isArray(c.images) && c.images.length > 1) {
            reconstructedMap[primary] = c.images.filter((u: string) => u && u !== primary).slice(0, 5);
          }
        }
      });
      setWizardDetailedImagesByPrimary(reconstructedMap);
    } else {
      setWizardDetailedImagesByPrimary({});
    }
    setWizardColorStockTrackingEnabled(Boolean(prod.colorStockTrackingEnabled));
    if (prod.colors && prod.colors.length > 0) {
      setWizardColorSwatches(
        prod.colors.map((c: any) => ({
          name: typeof c === "string" ? c : c.name,
          hex: typeof c === "object" && c.hex ? c.hex : "#6366f1",
          images: typeof c === "object" && c.images ? c.images : (c.imageUrl ? [c.imageUrl] : []),
          imageUrl: typeof c === "object" && c.imageUrl ? c.imageUrl : (c.image || ""),
          isHot: typeof c === "object" ? !!c.isHot : false,
          price: typeof c === "object" && typeof c.price === "number" ? c.price : undefined,
          stock: typeof c === "object" && c.stock !== undefined ? c.stock : undefined
        }))
      );
    } else {
      setWizardColorSwatches([]);
    }
    setWizardLandingPageContent(prod.uploadedLandingPageContent || "");
    setWizardLandingPageFileName(prod.uploadedLandingPageContent ? "custom_landing_page.html" : "");
    setWizardAdvancedStoryEnabled(!!prod.advancedLandingPageEnabled);
    let loadedStorySections: Array<{ id: string; url: string; description?: string }> = [];
    if (prod.advancedProductStorySections && Array.isArray(prod.advancedProductStorySections) && prod.advancedProductStorySections.length > 0) {
      loadedStorySections = prod.advancedProductStorySections.map((item: any, idx: number) => ({
        id: typeof item === 'object' && item.id ? item.id : `story-${Date.now()}-${idx}`,
        url: typeof item === 'string' ? item : (item.url || item.image || ''),
        description: typeof item === 'object' ? (item.description || '') : ''
      })).filter((it: any) => it.url);
    } else if (prod.uploadedLandingPageContent) {
      const regex = /<img[^>]+src="([^">]+)"/g;
      let match;
      let idx = 0;
      while ((match = regex.exec(prod.uploadedLandingPageContent)) !== null) {
        if (match[1]) {
          loadedStorySections.push({ id: `story-ext-${idx}`, url: match[1], description: '' });
          idx++;
        }
      }
    }
    setWizardAdvancedStorySections(loadedStorySections);
    setWizardStoryDescriptionEnabled(loadedStorySections.some(s => !!s.description && s.description.trim() !== ''));
    
    setWizardVariantsEnabled(prod.variants && prod.variants.length > 0 ? true : false);
    setWizardProductVariants(prod.variants && Array.isArray(prod.variants) ? JSON.parse(JSON.stringify(prod.variants)) : []);
    
    // Reconstruct wizardVariantAttrs so seller can edit existing variant attributes and tags without data loss
    const reconstructedAttrs: Array<{ name: string; tags: string[] }> = [];
    if (prod.variants && Array.isArray(prod.variants) && prod.variants.length > 0) {
      prod.variants.forEach((v: any) => {
        if (v.options && typeof v.options === "object") {
          Object.entries(v.options).forEach(([optName, optVal]) => {
            let existing = reconstructedAttrs.find(a => a.name.toLowerCase() === optName.toLowerCase());
            if (!existing) {
              existing = { name: optName, tags: [] };
              reconstructedAttrs.push(existing);
            }
            if (optVal && !existing.tags.includes(String(optVal))) {
              existing.tags.push(String(optVal));
            }
          });
        }
      });
    }

    if (prod.colors && Array.isArray(prod.colors) && prod.colors.length > 0) {
      let colorAttr = reconstructedAttrs.find(a => ["color", "couleur", "لون", "اللون"].some(c => a.name.toLowerCase().includes(c)));
      if (!colorAttr) {
        colorAttr = { name: "Color", tags: [] };
        reconstructedAttrs.unshift(colorAttr);
      }
      prod.colors.forEach((c: any) => {
        const cName = typeof c === "string" ? c : c.name;
        if (cName && !colorAttr.tags.includes(cName)) {
          colorAttr.tags.push(cName);
        }
      });
    }

    if (prod.sizes && Array.isArray(prod.sizes) && prod.sizes.length > 0) {
      let sizeAttr = reconstructedAttrs.find(a => ["size", "taille", "مقاس", "حجم"].some(s => a.name.toLowerCase().includes(s)));
      if (!sizeAttr) {
        sizeAttr = { name: "Size", tags: [] };
        reconstructedAttrs.push(sizeAttr);
      }
      prod.sizes.forEach((s: any) => {
        if (s && !sizeAttr.tags.includes(String(s))) {
          sizeAttr.tags.push(String(s));
        }
      });
    }

    setWizardVariantAttrs(reconstructedAttrs);

    setWizardBundleEnabled(!!prod.isBundle);
    setWizardBundleItems(prod.bundleItems && Array.isArray(prod.bundleItems) ? JSON.parse(JSON.stringify(prod.bundleItems)) : []);
    setWizardBundlePrice(prod.bundlePrice !== undefined ? prod.bundlePrice : prod.price);
    setWizardOffersConfig(
      prod.offersConfig
        ? JSON.parse(JSON.stringify(prod.offersConfig))
        : createDefaultOffersConfig(Number(prod.price) || 3500, prod.imageUrl)
    );
    setWizardSizingFitConfig(
      prod.sizingFitConfig
        ? JSON.parse(JSON.stringify(prod.sizingFitConfig))
        : undefined
    );

    setWizardStock(prod.stock !== undefined ? prod.stock : 10);
    setWizardDiscountEnabled(!!prod.discountEnabled);
    setWizardDiscountPercent(prod.discountPercent !== undefined ? prod.discountPercent : 15);
    setWizardTimerEnabled(!!prod.timerEnabled);
    setWizardTimerHours(prod.timerHours !== undefined ? prod.timerHours : 24);
    setWizardTimerIsCustom(prod.timerHours !== undefined && ![12, 24, 36].includes(prod.timerHours));
    setWizardTimerStyle((prod.timerStyle || "style_1") as FlashSaleTimerStyle);
    setWizardCurrency(prod.currency || myStore.currency || "DZD");
    setWizardSeoKeywords(prod.hashtags || "");
    setShowWizardLivePreview(false); // Standard mode: Full Form
    setWizardShowHints(false); // Standard mode: Hints OFF
    
    setMerchantSubTab("new-product-blank");
  };

