  const handleDeleteProduct = (productId: string) => {
    if (!checkPermission("manageProducts", "Delete Product", "Manage Products")) return;

    setStores((prevStores) =>
      prevStores.map((s) => {
        if (s.id === myStore.id) {
          return {
            ...s,
            products: s.products.filter((p) => p.id !== productId),
          };
        }
        return s;
      })
    );
    setMerchantFeedbackMessage("Product deleted successfully.");
    setShowDeleteConfirmId(null);
  };

  // --- Bulk Product Action Handlers ---
  const handleBulkDelete = () => {
    if (!checkPermission("manageProducts", "Delete Products in Bulk", "Manage Products")) return;
    setStores((prevStores) =>
      prevStores.map((s) => {
        if (s.id === myStore.id) {
          return {
            ...s,
            products: s.products.filter((p) => !selectedProductIds.includes(p.id)),
          };
        }
        return s;
      })
    );
    setMerchantFeedbackMessage(`Successfully deleted ${selectedProductIds.length} products.`);
    setSelectedProductIds([]);
  };

  const handleBulkPause = () => {
    if (!checkPermission("manageProducts", "Pause Products in Bulk", "Manage Products")) return;
    setStores((prevStores) =>
      prevStores.map((s) => {
        if (s.id === myStore.id) {
          return {
            ...s,
            products: s.products.map((p) =>
              selectedProductIds.includes(p.id) ? { ...p, status: "draft" as const } : p
            ),
          };
        }
        return s;
      })
    );
    setMerchantFeedbackMessage(`Successfully paused (set as draft) ${selectedProductIds.length} products.`);
    setSelectedProductIds([]);
  };

